describe('Modal with Video - Pause on Close', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.get('[data-testid="open-video-modal"]').should('be.visible');
  });

  it('should pause video when modal is closed', () => {
    // Open the modal
    cy.get('[data-testid="open-video-modal"]').click();

    // Verify modal is visible
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Verify video element exists and is playing
    cy.get('[data-testid="modal-video"]')
      .should('exist')
      .then(($video) => {
        expect($video[0].paused).to.equal(false);
      });

    // Play the video to ensure it's in playing state
    cy.get('[data-testid="modal-video"]').then(($video) => {
      $video[0].play();
    });

    // Close modal using close button
    cy.get('[data-testid="modal-close-button"]').click();

    // Verify modal is closed
    cy.get('[data-testid="video-modal"]').should('not.be.visible');

    // Verify video is paused
    cy.get('[data-testid="modal-video"]').then(($video) => {
      expect($video[0].paused).to.equal(true);
    });
  });

  it('should pause video when modal is closed via overlay click', () => {
    // Open the modal
    cy.get('[data-testid="open-video-modal"]').click();

    // Verify modal is visible
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Play the video
    cy.get('[data-testid="modal-video"]').then(($video) => {
      $video[0].play();
    });

    // Wait a moment to ensure video is playing
    cy.wait(500);

    // Verify video is playing before closing
    cy.get('[data-testid="modal-video"]').then(($video) => {
      expect($video[0].paused).to.equal(false);
    });

    // Close modal by clicking on overlay
    cy.get('[data-testid="modal-overlay"]').click({ force: true });

    // Verify modal is closed
    cy.get('[data-testid="video-modal"]').should('not.be.visible');

    // Verify video is paused
    cy.get('[data-testid="modal-video"]').then(($video) => {
      expect($video[0].paused).to.equal(true);
    });
  });

  it('should handle rapid open/close cycles without errors', () => {
    for (let i = 0; i < 3; i++) {
      // Open modal
      cy.get('[data-testid="open-video-modal"]').click();
      cy.get('[data-testid="video-modal"]').should('be.visible');

      // Play video
      cy.get('[data-testid="modal-video"]').then(($video) => {
        $video[0].play();
      });

      cy.wait(300);

      // Close modal
      cy.get('[data-testid="modal-close-button"]').click();
      cy.get('[data-testid="video-modal"]').should('not.be.visible');

      // Verify video is paused
      cy.get('[data-testid="modal-video"]').then(($video) => {
        expect($video[0].paused).to.equal(true);
      });

      cy.wait(200);
    }
  });

  it('should maintain video pause state after reopening modal', () => {
    // Open modal
    cy.get('[data-testid="open-video-modal"]').click();
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Play video
    cy.get('[data-testid="modal-video"]').then(($video) => {
      $video[0].play();
    });

    cy.wait(500);

    // Close modal
    cy.get('[data-testid="modal-close-button"]').click();
    cy.get('[data-testid="video-modal"]').should('not.be.visible');

    // Verify video is paused
    cy.get('[data-testid="modal-video"]').then(($video) => {
      expect($video[0].paused).to.equal(true);
    });

    // Reopen modal
    cy.get('[data-testid="open-video-modal"]').click();
    cy.get('[data-testid="video-modal"]').should('be.visible');

    // Verify video is still paused (not auto-playing)
    cy.get('[data-testid="modal-video"]').then(($video) => {
      expect($video[0].paused).to.equal(true);
    });
  });
});
